    {
      "indicator": "Fechamento",
      "reading": "9.65",
      "interpretation": "Fechamento acima da MM20/EMA9/EMA21 mas ligeiramente abaixo da MM50 — posição neutra com leve viés de alta."
    },
    {
      "indicator": "MM20",
      "reading": "9.3350",
      "interpretation": "MM20 abaixo da MM50; atua como suporte imediato (consolidação no curto prazo)."
    },
    {
      "indicator": "MM50",
      "reading": "9.6864",
      "interpretation": "MM50 acima da MM200 -> tendência de médio prazo ainda positiva; resistência próxima (preço 9,65 < MM50)."
    },
    {
      "indicator": "MM200",
      "reading": "9.0174",
      "interpretation": "MM200 abaixo do preço => suporte estrutural de longo prazo; quebra abaixo altera viés para baixa."
    },
    {
      "indicator": "EMA9",
      "reading": "9.4232",
      "interpretation": "EMA9 levemente abaixo da EMA21, porém abaixo do preço — curto prazo com leve suporte, sem forte aceleração."
    },
    {
      "indicator": "EMA21",
      "reading": "9.4473",
      "interpretation": "EMA21 sob o preço; confirma sustentação de curtíssimo prazo, mas EMAs mostram sinais mistos entre si."
    },
    {
      "indicator": "MACD",
      "reading": "MACD -0.0477 / Signal -0.0825 / Hist 0.0348",
      "interpretation": "MACD cruzou acima da linha de sinal (histograma positivo) — início de recuperação de momentum, porém ambos ainda negativos: sinal fraco."
    },
    {
      "indicator": "Bandas de Bollinger",
      "reading": "BB_lower 8.8177 / BB_mid 9.3350 / BB_upper 9.8523",
      "interpretation": "Preço entre média e banda superior; bandas com largura moderada; não há sinal de sobrecompra extrema."
    },
    {
      "indicator": "RSI14",
      "reading": "54.1910",
      "interpretation": "RSI neutro — sem condição de sobrecompra/sobrevenda; confirma necessidade de confirmação adicional."
    },
    {
      "indicator": "Volume",
      "reading": "5.6709908e+09",
      "interpretation": "Volume do dia é moderadamente elevado; altas recentes foram confirmadas por picos de volume, favorecendo movimentos ascendentes quando acompanhados por aumento de volume."
    }
  ]
}
